<?php
$admin_title='Categories'; require __DIR__.'/layout_top.php'; $pdo=db(); $edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='delete'){$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Category deleted.');redirect('admin/categories.php');}$name=trim($_POST['name']??'');$status=$_POST['status']==='inactive'?'inactive':'active';if(strlen($name)<2)throw new RuntimeException('Enter a valid category name.');if($action==='update'){$pdo->prepare('UPDATE categories SET name=?,status=? WHERE id=?')->execute([$name,$status,(int)$_POST['id']]);flash('success','Category updated.');}else{$pdo->prepare('INSERT INTO categories(name,status) VALUES(?,?)')->execute([$name,$status]);flash('success','Category added.');}redirect('admin/categories.php');}catch(PDOException $e){flash('error','Category name must be unique and cannot be deleted while products use it.');redirect('admin/categories.php');}catch(Throwable $e){flash('error',$e->getMessage());redirect('admin/categories.php');}}
if(isset($_GET['edit'])){$stmt=$pdo->prepare('SELECT * FROM categories WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch()?:null;}$categories=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();
?>
<div class="grid two" style="grid-template-columns:320px 1fr"><form class="admin-panel" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><span class="eyebrow" style="color:#ae7d2c">Product organization</span><h2 style="margin:8px 0 18px;font-size:28px"><?=$edit?'Edit category':'Add category'?></h2><div class="form-grid" style="grid-template-columns:1fr"><label>Name<input required name="name" value="<?=e($edit['name']??'')?>"></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label><button class="button dark"><?=$edit?'Save changes':'Add category'?></button><?php if($edit):?><a href="<?=url('admin/categories.php')?>">Cancel</a><?php endif;?></div></form><section class="admin-panel"><div class="admin-panel-head"><h3>All categories</h3><span class="muted"><?=count($categories)?> total</span></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Products</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><strong><?=e($c['name'])?></strong></td><td><?=e((string)$c['product_count'])?></td><td><?=e(ucfirst($c['status']))?></td><td><div class="actions"><a class="button small outline" href="?edit=<?=$c['id']?>">Edit</a><form method="post" data-confirm="delete"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="button small danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php require __DIR__.'/layout_bottom.php'; ?>
